function ground(p,g,t){if(root.RPG_JONGCHAN_PAINTED_FX?.ground(p,g,t))return;if(root.RPG_GREATSWORD_FX?.ground(p,g,t))return;if(g.s.active!==0||!g.c?.sword)return;load();const s=g.c.sword;p.save();p.lineWidth=1;p.strokeStyle='#78deea66';p.setLineDash([3,7]);for(let i=1;i<s.anchors.length;i++){p.beginPath();p.moveTo(s.anchors[i-1].x,s.anchors[i-1].y);p.lineTo(s.anchors[i].x,s.anchors[i].y);p.stroke();}if(s.anchors.length===3){p.beginPath();p.moveTo(s.anchors[2].x,s.anchors[2].y);p.lineTo(s.anchors[0].x,s.anchors[0].y);p.stroke();}p.restore();for(const a of s.anchors){if(!glyph?.complete||!glyph.naturalWidth)continue;p.save();p.globalAlpha=Math.min(1,a.life)*(.7+Math.sin(t*3+a.id)*.1);p.translate(a.x,a.y-2);p.scale(1,.58);p.imageSmoothingEnabled=false;p.drawImage(glyph,-25,-32,50,64);p.restore();}}
